def page(title, desc, main, css='', js='', closing=True, full=True):
    head = f'<title>{title}</title>\n<meta name="description" content="{desc}">\n' + FONTS + '\n<link rel="stylesheet" href="assets/site.css">\n'
    if css:
        head += '<style>\n' + css + '\n</style>\n'
    bodyc = NOISE + '\n' + LOGO + '\n' + MENU + '\n<main id="top">\n' + main + '\n' + (CLOSING if closing else '') + '\n</main>\n' + FOOTER + '\n<script src="assets/site.js"></script>\n' + (('<script>\n' + js + '\n</script>\n') if js else '')
    if full:
        return '<!doctype html>\n<html lang="de-CH">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">\n' + head + '</head>\n<body>\n' + bodyc + '</body>\n</html>\n'
    return head + bodyc

